<template>
	<view>
		<view class="full">
				<view class="full">
					<image style="width: 750upx;height: 0%;"></image><!-- 注意这里图片的高度，必须是偶数。否则在H5端的部分chrome版本上会触发chrome的bug，在标题栏下方会留下一条线的空隙 -->
				</view>
				<view class="sticky-box">
					<u-button class="custom-style" @click="jump"> 查看病历</u-button>
					<u-button class="custom-style" @tap='exit'> 结束问诊</u-button>
					
					
				</view>
			<view class="content">
		
				<!-- 聊天内容 -->
				<scroll-view class="chat" scroll-y="true" scroll-with-animation="true" :scroll-into-view="scrollToView">
					<view class="chat-main" :style="{paddingBottom:inputh+'px'}">
						<view class="chat-ls" v-for="(item,index) in unshiftmsg" :key="index" :id="'msg'+ index">
							<view class="chat-time" v-if="item.createTime != ''">{{changeTime(item.createTime)}}</view>
							<view class="msg-m msg-left" v-if="item.sendName == friendName">
								<image class="user-img" :src="src2"></image>
								<view class="message" v-if="item.TextType == 0">
									<!-- 文字 -->
									<view class="msg-text">{{item.sendText}}</view>
								</view>
								<view class="message" v-if="item.TextType == 1" @tap="previewImg(item.sendText)">
									<!-- 图像 -->
									<image :src="item.sendText" class="msg-img" mode="widthFix"></image>
								</view>
								<view class="message" v-if="item.TextType == 2" @tap="playVoice(item.sendText.voice)">
									<!-- 音频 -->
									<view class="msg-text voice" :style="{width:item.sendText.time*4+'rpx'}">
										<image src="../../static/logo.png" class="voice-img"></image>
										{{item.sendText.time}}″
									</view>
								</view>
							</view>
							<view class="msg-m msg-right" v-if="item.sendName != friendName" >
								<image class="user-img" :src="src1" ></image>
								<view class="message" v-if="item.TextType == 0">
									<view class="msg-text">{{item.sendText}}</view>
								</view>
								<view class="message" v-if="item.TextType == 1" @tap="previewImg(item.sendText)">
									<image :src="item.sendText" class="msg-img" mode="widthFix"></image>
								</view>
								<view class="message" v-if="item.TextType == 2" @tap="playVoice(item.sendText.voice)">
									<!-- 音频 -->
									<view class="msg-text voice" :style="{width:item.sendText.time*4+'rpx'}">
										{{item.sendText.time}}″
										<image src="../../static/logo.png" class="voice-img"></image>
									</view>
								</view>
								<view class="message" v-if="item.TextType == 3" @tap="openLocation(item.sendText)">
									<!-- 位置 -->
									<view class="msg-map">
										<view class="map-name">{{item.sendText.name}}</view>
										<view class="map-address">{{item.sendText.address}}</view>
										<map class="map" :longitude="item.sendText.longitude" :latitude="item.sendText.latitude"
											:markers="covers(item.sendText)"></map>
									</view>
								</view>
							</view>
						</view>
					</view>
				</scroll-view>
				<submit @inputs="inputs" @heights="heights"></submit>
				
		</view>
		
		
	</view>
		
		
	</view>
	
</template>

<script>
	import dateTime from '../../common/dataTime.js';
	import submit from '../../components/submit/submit.vue';
	// 以下路径需根据项目实际情况填写
	import {pathToBase64,base64ToPath} from '../../js_sdk/mmmm-image-tools/index.js'

	
	//音频播放
	const innerAudioContext = uni.createInnerAudioContext();

	export default {
		data() {
			return {
				imgUrl:'',

				src1:"",
				src2:"",
				friendName: "doctor",
				msg: [
					// {
					// 	"sendName": "patient",
					// 	"receviceName": "doctor",
					// 	"sendText": "https://img1.baidu.com/it/u=1296373114,158338416&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667",
					// 	"createTime": new Date(),
					// 	"updateTime": new Date(),
					// 	"TextType": 1
					// },
					// {
					// 	"sendName": "patient",
					// 	"receviceName": "doctor",
					// 	"sendText": "没受过伤，有片子，您稍等",
					// 	"createTime": new Date(),
					// 	"updateTime": new Date(),
					// 	"TextType": 0
					// },
					// {
					// 	"sendName": "doctor",
					// 	"receviceName": "patient",
					// 	"sendText": "好的，你过去有过什么受伤的经历吗？或者受伤之后有拍过片子吗？",
					// 	"createTime": new Date(),
					// 	"updateTime": new Date(),
					// 	"TextType": 0
					// },
					// {
					// 	"sendName": "patient",
					// 	"receviceName": "doctor",
					// 	"sendText": "你好，我最近可能运动受伤了，想咨询一些问题",
					// 	"createTime": new Date(),
					// 	"updateTime": new Date(),
					// 	"TextType": 0
					// },
					// {
					// 	"sendName": "doctor",
					// 	"receviceName": "patient",
					// 	"sendText": "您好，请问您有什么问题？",
					// 	"createTime": new Date(),
					// 	"updateTime": new Date(),
					// 	"TextType": 0
					// },
					
				],
			
				// 反转数据接收
				unshiftmsg: [],
				imgMsg: [],
				scrollToView: '',
				oldTime: new Date(),
				inputh: '60',
				 
				socketTask: null,
				// 确保websocket是打开状态,初始未打开
				is_open_socket: false,
				message_itext : "",
				response : ""
			}
		},
		onLoad() {
			// 进入这个页面的时候创建websocket连接,整个页面随时使用
			this.getImage();
			this.connectSocketInit();
			this.getMessage();
			
		},
		beforeDestroy() {
			this.closeSocket();
		},
		onShow() {
			// 数组倒叙 主要是应对后端传过来的数据
			for (var i = 0; i < this.msg.length; i++) {
				//时间间隔处理
				if (i < this.msg.length - 1) { //这里表示头部时间还是显示一下
					let t = dateTime.spaceTime(this.oldTime, this.msg[i].createTime);
					if (t) {
						this.oldTime = t;
					}
					this.msg[i].createTime = t;
				}
				// 获取图片，为下面的预览做准备
				if (this.msg[i].TextType == 1) {
					this.imgMsg.unshift(this.msg[i].sendText)
				}
				this.unshiftmsg.unshift(this.msg[i]);
			}
			// 跳转到最后一条数据 与前面的:id进行对照
			this.$nextTick(function() {
				this.scrollToView = 'msg' + (this.unshiftmsg.length - 1)
			})
		},
		components: {
			submit,
		},
		methods: {
			get(){
				let data = "data:image/png;base64,"
				let result = data.replace(/[\r\n]/g, "");
				let pdfBase64 = `data:application/pdf;base64,${result}`;
				    base64ToPath(pdfBase64)
				      .then(path => {
				        console.log(path)
						
				      })
				      .catch(error => {
				        console.error(error)
				      })
			},
			getImage(){
				let type = uni.getStorageSync("usertype")
				if(type==1){
					this.src1 = "../../static/QQ图片20230407115216.jpg"
					this.src2 = "../../static/doctor2.png"
				}else{
					this.src2 = "../../static/QQ图片20230407115216.jpg"
					this.src1 = "../../static/doctor2.png"
				}
				
			},
			jump(){
				uni.navigateTo({
					url:"/pages/inquiry/patient_illness"
				})
			},
			getMessage(){
				// let list={
				// 	"sendName": "doctor",
				// 	"receviceName": "patient",
				// 	"sendText": "zhoahwfoa",
				// 	"createTime": new Date(),
				// 	"updateTime": new Date(),
				// 	"TextType": 0
				// }
				let type = uni.getStorageSync('usertype');
				//let send_id = uni.getStorageSync("username")
				//let receive_id = uni.getStorageSync("doctor_id")
				//console.log("asdas"+send_id)
				//console.log(receive_id)
				//console.log("asdasda"+type)
				let send_id = 0
				let receive_id = 0
				
				if(type==1){
					send_id = uni.getStorageSync("username")
					receive_id = uni.getStorageSync("doctor_id")
					//console.log(send_id)
					//console.log(receive_id)
				}else{
					send_id =uni.getStorageSync("us")
					console.log('asdasd'+send_id)
					receive_id = uni.getStorageSync("username")
				}
				let iid = uni.getStorageSync("illid")
				let id = String(iid)
				console.log(id)
				console.log('sdasd'+send_id)
				//console.log("sdasd"+typeof(send_id))
				//console.log("sadsdas"+typeof(receive_id))
				uni.request({
					url:'http://10.0.2.2:8080/msg/selectMsg',
					//安卓模拟器的本机地址，等同于127.0.0.1
					method:"GET",
					header: {
						"Content-Type": "application/json"
					},
					data:{ 
						sendUserName:send_id,
						receiveUserName: receive_id,
						illid:id
					},
					success: (res) => {
						console.log(res.data)
						
						let length = res.data.length
					//	console.log(length)
					//	console.log(res.data[2])
						if(length==0){
							let primary = {
								"illid":id,
								"sendUserName":send_id,
								"receiveUserName":receive_id,
								"sendName": "doctor",
								"receviceName": "patient",
								"sendText": "请问您有什么问题",
								"createTime": new Date(),
								"updateTime": new Date(),
								"TextType": 0
							}
							
							
							console.log(typeof(id))
							
							uni.request({
								url:'http://10.0.2.2:8080/msg/addMsg',
								header: {
									"Content-Type": "application/json"
								},
								data:({
									"illid":id,
									"sendUserName":send_id,
									"receiveUserName":receive_id,
									"sendName": "doctor",
									"receiveName": "patient",
									"sendText": "请问您有什么问题",
									"createTime": new Date(),
									"updateTime": new Date(),
									"TextType": 0
								}),
								method:'POST',
								success: function(res){
								//	console.log(res)
								//	console.log(res.data[2])
								
								}.bind(this)
							})
							let type = uni.getStorageSync('usertype');
							// console.log(type)
							if(type == 1){
								
								this.unshiftmsg.push(primary);
								// 跳转到最后一条数据 与前面的:id进行对照
								this.$nextTick(function() {
									this.scrollToView = 'msg' + (this.unshiftmsg.length - 1)
								})
							}
							
						}
						
						
						for(let i=0;i<length;i++){
							let tp = res.data[i].TextType
							console.log(tp)
							
							let list_temp=res.data[i];
							
							let type = uni.getStorageSync('usertype');
							console.log(list_temp.sendName)
							if(type==2){
								if(list_temp.sendName == "doctor"){
									list_temp.sendName = "patient";
									list_temp.receiveName = "doctor";
								}else{
									list_temp.sendName = "doctor";
									list_temp.receiveName = "patient";
								}
							}else{
								if(list_temp.sendName == "patient"){
									list_temp.sendName = "patient";
									list_temp.receiveName = "doctor";
								}else{
									list_temp.sendName = "doctor";
									list_temp.receiveName = "patient";
								}
							}
			
							this.unshiftmsg.push(list_temp);
							// 跳转到最后一条数据 与前面的:id进行对照
							this.$nextTick(function() {
								this.scrollToView = 'msg' + (this.unshiftmsg.length - 1)
							})
						}
					}
				})
				
			},
			
			connectSocketInit() {
				// 创建一个this.socketTask对象,发送、接收、关闭socket都由这个对象操作
				this.socketTask = uni.connectSocket({
					// 【非常重要】必须确保你的服务器是成功的
					url: "ws://10.0.2.2:8804/ws",	// 此处地址最好不要127.0.0.1,不然手机调试的时候忘记改就会出错
					success(data) {
						console.log("websocket连接成功");
					}
				});
			 
				// 消息的发送和接收必须在正常连接打开中,才能发送或接收,否则会失败
				this.socketTask.onOpen((res) => {
					console.log("WebSocket连接正常打开中...");
					this.is_open_socket = true;
				})
				
				
				// 注：只有连接正常打开中 ，才能正常收到消息
				this.socketTask.onMessage((res) => {
					console.log("收到服务器内容：" + res.data);
					let list = {
						"sendName": "doctor",
						"receviceName": "patient",
						"sendText": res.data,
						"createTime": new Date(),
						"updateTime": new Date(),
						"TextType": 0
					};
					let type = uni.getStorageSync('usertype')
					if(type==2&&list.sendName!="doctor"){
						this.unshiftmsg.push(list);
						// 跳转到最后一条数据 与前面的:id进行对照
						this.$nextTick(function() {
							this.scrollToView = 'msg' + (this.unshiftmsg.length - 1)
						})
					}
					// 发送给服务器消息
					//onSendWS(JSON.stringify(data));
					//this.clickRequest(res.data.sendText);
					
				});
				// 这里仅是事件监听,如果socket关闭了会执行
				this.socketTask.onClose(() => {
					console.log("已经被关闭了")
				})
				
			},
			// 关闭websocket,离开这个页面的时候执行关闭
			closeSocket() {
				this.socketTask.close({
					success:function(res) {
						this.is_open_socket = false;
						console.log("关闭成功", res)
					}.bind(this),
					fail(err) {
						console.log("关闭失败", err)
					}
				})
			},
			exit(){
				let usertype = uni.getStorageSync('usertype')
				
				console.log(usertype)
				if(usertype==2){
					uni.navigateTo({
						url:'/pages/inquiry/inquiry_conclusion'
					})
				}else if(usertype==1){
					uni.navigateTo({
						url:'/pages/inquiry/doctor_rate'
					})
				}
				uni.removeStorageSync("illid")
			},
			changeTime(date) {
				return dateTime.dateTime1(date);
			},
			// 进行图片的预览
			previewImg(e) {
				let index = 0;
				for (let i = 0; i < this.imgMsg.length; i++) {
					if (this.imgMsg[i] == e) {
						index = i;
					}
				}
				console.log("index", index)
				// 预览图片
				uni.previewImage({
					current: index,
					urls: this.imgMsg,
					longPressActions: {
						itemList: ['发送给朋友', '保存图片', '收藏'],
						success: function(data) {
							console.log('选中了第' + (data.tapIndex + 1) + '个按钮,第' + (data.index + 1) + '张图片');
						},
						fail: function(err) {
							console.log(err.errMsg);
						}
					}
				});
			},
			//音频播放
			playVoice(e) {
				innerAudioContext.src = e;
				innerAudioContext.onPlay(() => {
					console.log('开始播放');
				});
			},
			clickRequest(e) {
				if (this.is_open_socket) {
					// 发送消息,同时返回一组数据
					this.socketTask.send({
						data: e,
						async success() {	// 同步接收
							console.log("消息发送成功");
						},
					});
				}
			},
			//接受输入内容
			inputs(e) {
				let type = uni.getStorageSync('usertype');
				//let send_id = uni.getStorageSync("username")
				//let receive_id = uni.getStorageSync("doctor_id")
				//console.log("asdas"+send_id)
				//console.log(receive_id)
				//console.log("asdasda"+type)
				let send_id = 0
				let receive_id = 0
				
				if(type==1){
					send_id = uni.getStorageSync("username")
					receive_id = uni.getStorageSync("doctor_id")
					//console.log(send_id)
					//console.log(receive_id)
				}else{
					send_id =uni.getStorageSync("us")
					receive_id = uni.getStorageSync("username")
				}
				let tp = e.type
				console.log("sda"+tp)
				if(tp==1){
					
					//console.log("sdss "+tp)
					let temp = uni.getStorageSync("base64")
					let iid = uni.getStorageSync("illid")
					let id = String(iid)
					//时间间隔处理
					console.log(e)
					let data = {
						"sendName": "patient",
						"receviceName": "doctor",
						"sendText": temp,
						"createTime": new Date(),
						"updateTime": new Date(),
						"TextType": e.type
					};
					
					
					// 发送给服务器消息
					//onSendWS(JSON.stringify(data));
					this.clickRequest(data.sendText);
					let type = uni.getStorageSync('usertype')
					if(type == 2){
						e.send_name = "doctor"
						e.receive_name = "patient"
					}else{
						e.send_name = "patient"
						e.receive_name = "doctor"
					}
					
					uni.request({
						url:'http://10.0.2.2:8080/msg/addMsg',
						header: {
							"Content-Type": "application/json"
						},
					
						data:({
							illid:id,
							sendUserName:send_id,
							receiveUserName:receive_id,
							sendName: e.send_name,
							receiveName: e.receive_name,
							sendText: temp,
							createTime: new Date(),
							updateTime: new Date(),
							TextType: e.type
						}),
						method:'POST',
						success: function(res) {
						//	console.log(res)
						//	console.log(res.data[2])
						
						}.bind(this)
					})
					this.unshiftmsg.push(data);
					// 跳转到最后一条数据 与前面的:id进行对照
					this.$nextTick(function() {
						this.scrollToView = 'msg' + (this.unshiftmsg.length - 1)
					})
					if (e.type == 1) {
						this.imgMsg.push(e.message);
					}
					console.log(e)
				}else{
					let iid = uni.getStorageSync("illid")
					let id = String(iid)
					//时间间隔处理
					console.log(e)
					let data = {
						"sendName": "patient",
						"receviceName": "doctor",
						"sendText": e.message,
						"createTime": new Date(),
						"updateTime": new Date(),
						"TextType": e.type
					};
					
					
					// 发送给服务器消息
					//onSendWS(JSON.stringify(data));
					this.clickRequest(data.sendText);
					let type = uni.getStorageSync('usertype')
					if(type == 2){
						e.send_name = "doctor"
						e.receive_name = "patient"
					}else{
						e.send_name = "patient"
						e.receive_name = "doctor"
					}
					
					uni.request({
						url:'http://10.0.2.2:8080/msg/addMsg',
						header: {
							"Content-Type": "application/json"
						},
					
						data:({
							illid:id,
							sendUserName:send_id,
							receiveUserName:receive_id,
							sendName: e.send_name,
							receiveName: e.receive_name,
							sendText: e.message,
							createTime: new Date(),
							updateTime: new Date(),
							TextType: e.type
						}),
						method:'POST',
						success: function(res) {
						//	console.log(res)
						//	console.log(res.data[2])
						
						}.bind(this)
					})
					this.unshiftmsg.push(data);
					// 跳转到最后一条数据 与前面的:id进行对照
					this.$nextTick(function() {
						this.scrollToView = 'msg' + (this.unshiftmsg.length - 1)
					})
					if (e.type == 1) {
						this.imgMsg.push(e.message);
					}
					console.log(e)
				}
				
				
			},
			//输入框高度
			heights(e) {
				console.log("高度:", e)
				this.inputh = e;
				this.goBottom();
			},
			// 滚动到底部
			goBottom() {
				this.scrollToView = '';
				this.$nextTick(function() {
					this.scrollToView = 'msg' + (this.unshiftmsg.length - 1)
				})
			}
		}
	}
</script>

